  ('e1d0b9c9-bb96-4c21-a2b0-d33f9b363dd4', '0243727527', 'jhs1-twi-t9-abawobo', 'Ghanaian Language (Akuapem Twi)', 'Outdooring 8th Day Timing', 'Nnafua ahe na Akanfo twɛn ansa na wɔabɔ abawobɔ na wɔato abofra foforo din?', 'C', 'B', '2026-10-20 19:01:42.193+00'),
  ('6f5f96df-2b60-4976-a1da-5db4f253bef1', '0243727527', 'jhs1-sci-t4-elements', 'Integrated Science', 'Definition of an Element', 'What is the correct definition of an ELEMENT?', 'A', 'B', '2026-10-20 19:07:48.265+00'),
  ('6d21d92a-9f2c-4eb1-a76b-a881c77d65a5', '0243727527', 'jhs1-sci-t4-elements', 'Integrated Science', 'Latin Roots of Chemical Symbols', 'What is the Latin name from which the chemical symbol Fe (Iron) was derived?', 'C', 'A', '2026-10-20 19:07:48.318+00'),
  ('9d1d0b29-b233-491f-9b78-028dee9e15cb', '0549387941', 'shs3-soc-t1-globalization-challenges-ghana', 'Social Studies', 'Cultural Imperialism', 'The phenomenon where indigenous African cultural values, music, fashion, and moral traditions are overwhelmed and replaced by Western consumer lifestyles through mass media is called:', 'B', 'A', '2026-10-20 19:54:24.654+00'),
  ('2554eb8b-6898-4637-b85f-d590860c356d', '0549387941', 'shs3-soc-t1-globalization-challenges-ghana', 'Social Studies', 'Role of the WTO', 'Which multilateral institution is responsible for establishing global trade rules and resolving trade disputes between sovereign nations?', 'D', 'A', '2026-10-20 19:54:24.748+00'),
