  ('bd75eb54-f85a-40b1-945e-252955d249db', '0549387941', 'shs3-soc-t1-international-cooperation-un-au', 'Social Studies', 'ECOWAS Free Movement Protocol', 'Under the ECOWAS Protocol on the Free Movement of Persons, Rights of Residence and Establishment, citizens of member states have the right to:', 'B', 'A', '2026-10-20 20:00:25.98+00'),
