  ('993afc5d-c2d2-497f-9d9b-a87ed2cbbb9c', '0549387941', 'shs3-soc-t1-development-planning-policies', 'Social Studies', 'Ghana Vision 2020', 'Which long-term national development blueprint launched in the 1990s envisioned Ghana attaining middle-income developed nation status by the year 2020?', 'D', 'A', '2026-10-20 20:23:55.989+00'),
  ('3f6ec4fb-fce5-4716-9ae6-c753c0067b5c', '0549387941', 'shs3-soc-t1-development-planning-policies', 'Social Studies', 'Nkrumah''s Seven-Year Development Plan', 'Which historic development plan launched by Dr. Kwame Nkrumah in 1964 was prematurely aborted by the February 1966 military coup?', 'C', 'A', '2026-10-20 20:23:56.097+00'),
